module json_owned;
import std.json;
import std.binary;
import std.byte_buffer;
auto entry(builtin::ByteRegion region,i64 n,i64 flag)->i64{builtin::OwnedBytes owner=region.try_allocate(8);const builtin::span<const u8> view=borrow_bytes(owner);const std::JsonTokenResult token=std::next_json_token(view,0,0);const std::JsonResult document=std::validate_json(view,0,0);owner.set(0,48u8);return document.token_count();}
